package config

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

// OrgSnapshot is the vendored view of hybrid-platforms/org team data.
// Generated by `make configs-snapshot` from a local org repo checkout.
// Never hand-edit: regenerate instead.
type OrgSnapshot struct {
	Source OrgSource          `yaml:"source"`
	Teams  map[string]OrgTeam `yaml:"teams"`
}

type OrgSource struct {
	Repo        string `yaml:"repo"`
	SHA         string `yaml:"sha,omitempty"`
	GeneratedAt string `yaml:"generated_at"`
}

// OrgTeam is one team from the org repo, keyed by team file basename
// (e.g. rosa_svc_cli_terraform). The same key is used as the `team:` value
// in the lean CI status registry.
type OrgTeam struct {
	DisplayName  string        `yaml:"display_name"`
	JiraTeamID   string        `yaml:"jira_team_id,omitempty"`
	SlackChannel string        `yaml:"slack_channel,omitempty"`
	Escalation   OrgEscalation `yaml:"escalation"`
	Components   []string      `yaml:"components"`
}

// OrgEscalation is the first person to ping when a team misses a ladder
// clock. Person is a org-repo user id (kerberos).
type OrgEscalation struct {
	Type   string `yaml:"type"`
	Person string `yaml:"person"`
}

const orgTeamsDir = "config/structures/hybrid_platforms/rosa/teams"

var jiraTeamURLRe = regexp.MustCompile(`people/team/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})`)

func LoadOrgSnapshot(path string) (*OrgSnapshot, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("failed to read org snapshot %s: %w", path, err)
	}
	var snap OrgSnapshot
	if err := yaml.Unmarshal(data, &snap); err != nil {
		return nil, fmt.Errorf("failed to parse org snapshot %s: %w", path, err)
	}
	return &snap, nil
}

// SnapshotFromOrg walks the ROSA teams in an org repo checkout and builds
// the snapshot. Output is deterministic (sorted keys and lists) apart from
// Source.GeneratedAt.
func SnapshotFromOrg(orgPath string) (*OrgSnapshot, error) {
	teamsDir := filepath.Join(orgPath, orgTeamsDir)
	entries, err := os.ReadDir(teamsDir)
	if err != nil {
		return nil, fmt.Errorf("failed to read %s (is this an org repo checkout?): %w", teamsDir, err)
	}

	snap := &OrgSnapshot{
		Source: OrgSource{
			Repo:        gitOrigin(orgPath),
			SHA:         gitHead(orgPath),
			GeneratedAt: time.Now().UTC().Format(time.RFC3339),
		},
		Teams: map[string]OrgTeam{},
	}

	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".yaml") {
			continue
		}
		team, err := snapshotTeam(orgPath, filepath.Join(teamsDir, entry.Name()))
		if err != nil {
			return nil, err
		}
		snap.Teams[strings.TrimSuffix(entry.Name(), ".yaml")] = *team
	}
	if len(snap.Teams) == 0 {
		return nil, fmt.Errorf("no teams found under %s", teamsDir)
	}
	return snap, nil
}

func snapshotTeam(orgPath, teamPath string) (*OrgTeam, error) {
	data, err := os.ReadFile(teamPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read %s: %w", teamPath, err)
	}
	var file map[string]any
	if err := yaml.Unmarshal(data, &file); err != nil {
		return nil, fmt.Errorf("failed to parse %s: %w", teamPath, err)
	}
	group, _ := file["group"].(map[string]any)

	team := &OrgTeam{
		DisplayName:  asString(file["name"]),
		JiraTeamID:   jiraTeamID(group),
		SlackChannel: slackChannel(group),
		Components:   teamComponents(group),
	}

	if person := rolePerson(group, "team_lead"); person != "" {
		team.Escalation = OrgEscalation{Type: "team_lead", Person: person}
	} else if person := rolePerson(group, "manager"); person != "" {
		team.Escalation = OrgEscalation{Type: "manager", Person: person}
	} else if parent := asString(group["parent"]); parent != "" {
		parentGroup, err := loadOrgGroup(orgPath, parent)
		if err != nil {
			return nil, err
		}
		if person := rolePerson(parentGroup, "manager"); person != "" {
			team.Escalation = OrgEscalation{Type: "parent_manager", Person: person}
		}
	}
	return team, nil
}

// loadOrgGroup resolves an org-internal reference like
// "c/structures/.../rosa_service_engineering.yaml" and returns its group map.
func loadOrgGroup(orgPath, ref string) (map[string]any, error) {
	path := ref
	if strings.HasPrefix(path, "c/") {
		path = "config/" + strings.TrimPrefix(path, "c/")
	}
	data, err := os.ReadFile(filepath.Join(orgPath, path))
	if err != nil {
		return nil, fmt.Errorf("failed to read org group %s: %w", ref, err)
	}
	var file map[string]any
	if err := yaml.Unmarshal(data, &file); err != nil {
		return nil, fmt.Errorf("failed to parse org group %s: %w", ref, err)
	}
	group, _ := file["group"].(map[string]any)
	return group, nil
}

func jiraTeamID(group map[string]any) string {
	for _, r := range asList(group["resources"]) {
		res, _ := r.(map[string]any)
		if asString(res["name"]) != "Jira Team" {
			continue
		}
		if m := jiraTeamURLRe.FindStringSubmatch(asString(res["url"])); m != nil {
			return m[1]
		}
	}
	return ""
}

// slackChannel prefers a team_internal channel and falls back to the first
// listed channel (e.g. a forum).
func slackChannel(group map[string]any) string {
	slack, _ := group["slack"].(map[string]any)
	first := ""
	for _, c := range asList(slack["channels"]) {
		ch, _ := c.(map[string]any)
		name := asString(ch["channel"])
		if name == "" {
			continue
		}
		if first == "" {
			first = name
		}
		for _, t := range asList(ch["types"]) {
			if asString(t) == "team_internal" {
				return name
			}
		}
	}
	return first
}

// rolePerson returns the first person id holding the given role.
func rolePerson(group map[string]any, role string) string {
	for _, r := range asList(group["roles"]) {
		roleEntry, _ := r.(map[string]any)
		matched := false
		for _, t := range asList(roleEntry["types"]) {
			if asString(t) == role {
				matched = true
			}
		}
		if !matched {
			continue
		}
		people, _ := roleEntry["people"].(map[string]any)
		for _, id := range asList(people["ids"]) {
			if s := asString(id); s != "" {
				return s
			}
		}
	}
	return ""
}

// teamComponents is the union of owned component_roles and jiras component
// entries, basename-normalized and sorted.
func teamComponents(group map[string]any) []string {
	seen := map[string]bool{}
	for _, c := range asList(group["component_roles"]) {
		entry, _ := c.(map[string]any)
		owner := false
		for _, t := range asList(entry["types"]) {
			if asString(t) == "owner" {
				owner = true
			}
		}
		if !owner {
			continue
		}
		name := componentRefName(asString(entry["component"]))
		if name != "" {
			seen[name] = true
		}
	}
	for _, j := range asList(group["jiras"]) {
		entry, _ := j.(map[string]any)
		if name := asString(entry["component"]); name != "" {
			seen[name] = true
		}
	}
	out := make([]string, 0, len(seen))
	for name := range seen {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

// componentRefName turns "c/software/system/openshift/components/rosa-cli.yaml"
// into "rosa-cli".
func componentRefName(ref string) string {
	if ref == "" {
		return ""
	}
	return strings.TrimSuffix(filepath.Base(ref), ".yaml")
}

func gitOrigin(orgPath string) string {
	return gitOutput(orgPath, "remote", "get-url", "origin")
}

func gitHead(orgPath string) string {
	return gitOutput(orgPath, "rev-parse", "HEAD")
}

func gitOutput(dir string, args ...string) string {
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	out, err := cmd.Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

func asString(v any) string {
	s, _ := v.(string)
	return s
}

func asList(v any) []any {
	l, _ := v.([]any)
	return l
}
